#include <fstream>
#include <iostream>
#include <string>

int main() {
    // Запись в текстовый файл
    {
        std::ofstream out("data.txt"); // RAII: файл закроется автоматически при выходе из блока
        if (!out) {
            std::cerr << "Не удалось открыть файл для записи\n";
            return 1;
        }
        out << "Привет, мир!\n";
        out << 42 << ' ' << 3.14 << '\n';
        // out.close() — не обязательно, деструктор вызовет fclose
    }

    // Чтение из текстового файла построчно
    {
        std::ifstream in("data.txt");
        if (!in) {
            std::cerr << "Файл не найден\n";
            return 1;
        }

        std::string line;
        while (std::getline(in, line)) { // читает строку до символа перевода строки
            std::cout << "Line: " << line << '\n';
        }

        // Чтение по токенам (разделённые пробелом или переводом строки)
        in.clear();                          // сбросить флаги ошибок
        in.seekg(0);                         // вернуть позицию чтения в начало файла
        std::string word;
        int num; double d;
        in >> word >> num >> d; // считывает "Привет," 42 3.14
    }

    // Бинарные файлы — запись и чтение «как есть», без преобразований
    {
        std::vector<int> data = {1, 2, 3, 4, 5};
        // Запись в бинарный файл
        std::ofstream bin_out("data.bin", std::ios::binary);
        bin_out.write(reinterpret_cast<const char*>(data.data()),
                      data.size() * sizeof(int));

        // Чтение из бинарного файла
        std::ifstream bin_in("data.bin", std::ios::binary);
        bin_in.seekg(0, std::ios::end);       // перейти в конец файла
        size_t size = bin_in.tellg() / sizeof(int); // узнать размер
        bin_in.seekg(0);                       // вернуться в начало
        std::vector<int> read_data(size);
        bin_in.read(reinterpret_cast<char*>(read_data.data()),
                    size * sizeof(int));
    }
}

