// Свои коды ошибок (C++11)
enum class MyErrc { Success = 0, NotFound, PermissionDenied };
// Нужна специализация std::is_error_code_enum<MyErrc> = true;
// Тогда make_error_code(MyErrc::NotFound) вернёт std::error_code

#include <expected>

std::expected<int, std::error_code> divide(int a, int b) {
    if (b == 0) return std::unexpected(std::make_error_code(std::errc::invalid_argument));
    return a / b;
}

auto result = divide(10, 0);
if (result) {
    std::cout << *result; // значение
} else {
    std::cerr << result.error().message(); // ошибка
}

// math.h — заголовочный файл (объявления)
#pragma once  // или include guards, чтобы файл не подключался дважды
#ifndef MATH_H
#define MATH_H

int add(int a, int b);        // объявление — компилятор знает, что функция существует
double pi();

#endif

// math.cpp — файл реализации
#include "math.h"
int add(int a, int b) { return a + b; }
constexpr double pi() { return 3.1415926535; }

// main.cpp — точка входа, использует объявления из заголовочного
#include "math.h"
#include <iostream>
int main() { std::cout << add(2, 3); }

